import 'package:text_parser/text_parser.dart';

void main() {
  const text = 'Contact us at support@example.com or visit https://example.com';
  final parser = TextParser(
    matchers: const [
      EmailMatcher(),
      UrlMatcher(),
    ],
  );
  final elements = parser.parseSync(text);
  elements.forEach(print);
}
